// Some portions generated by Claude
import {graphNodeSize} from './graph-geometry.ts';
import {measureLayoutConflicts} from './graph-layout.ts';
import {layoutNodeFixed} from './graph-layout-topology.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';
import type {Graph, PointerPosition} from './graph-types.ts';
import type {LayoutOptions} from './graph-layout-engine.ts';

export function layoutScoreGeometry(graph: Graph, positions: Map<string, PointerPosition>, options: LayoutOptions) {
  const index = new Map(graph.nodes.map((node, i) => [node.id, i]));
  return {
    nodes: graph.nodes.map(node => {
      const size = graphNodeSize(node);
      return {entityId: node.id, ...positions.get(node.id)!, width: size.width + gap.nodeGapX, height: size.height + gap.nodeGapY,
        renderWidth: size.width, renderHeight: size.height, fixed: layoutNodeFixed(node, options)};
    }),
    edges: graph.edges.flatMap(edge => {
      const a = index.get(edge.source), b = index.get(edge.target);
      return a !== undefined && b !== undefined && a !== b ? [[a, b] as [number, number]] : [];
    }),
  };
}

/** Bounded medium-graph selection objective. Readability dominates compactness;
 * both typical and long links matter, but cannot compensate for overlapping
 * node cards. Optimizing crossings alone can produce distant thin sectors.
 */
export function layoutCandidateScore(graph: Graph, positions: Map<string, PointerPosition>, options: LayoutOptions) {
  const g = layoutScoreGeometry(graph, positions, options), m = measureLayoutConflicts(g.nodes, g.edges);
  const lengths = g.edges.map(([a, b]) => Math.hypot(g.nodes[a].x - g.nodes[b].x, g.nodes[a].y - g.nodes[b].y)).sort((a, b) => a - b);
  const mean = lengths.reduce((sum, length) => sum + length, 0) / Math.max(1, lengths.length);
  const p95 = lengths[Math.floor(lengths.length * .95)] ?? 0;
  return m.nodeOverlaps * 100000 + m.edgeNodeOverlaps * 2 + m.edgeCrossings * 3 + mean / 10 + p95 / 10;
}
